using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioLoopCountValidation
{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static int checks,phase,hot;static string stage;static AnimationStudioWindow host;static MashBoxStudioViewport view;static StudioModelEditor editor;static Vector2 sent,point;static double next;static bool probe,renderPending;static Exception renderFailure;static Vector3[] original;static int[] polygons;static Quaternion cameraRotation;static Vector3 cameraPivot;static float cameraSize;
 static object Get(string name)=>typeof(StudioModelEditor).GetField(name,F).GetValue(editor);static void Set(string name,object value)=>typeof(StudioModelEditor).GetField(name,F).SetValue(editor,value);
 static object Call(string name,params object[] args)=>typeof(StudioModelEditor).GetMethods(F).Single(m=>m.Name==name&&m.GetParameters().Length==args.Length&&m.GetParameters().Select((p,i)=>args[i]==null||p.ParameterType.IsInstanceOfType(args[i])).All(v=>v)).Invoke(editor,args);
 static void Check(bool value,string message){if(!value)throw new Exception(stage+": "+message);checks++;}
 static void Reset(){UnityEditor.Undo.ClearAll();StudioUndo.ClearForTests();StudioUndo.IncrementCurrentGroup();}
 static void History(bool redo=false){UnityEditor.Undo.FlushUndoRecordObjects();StudioUndo.IncrementCurrentGroup();if(redo)StudioUndo.PerformRedo();else StudioUndo.PerformUndo();}
 static StudioModelDocument.Node Cube(){var mesh=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var p);return new StudioModelDocument.Node{name="Loop cube",mesh=mesh,cutPolygons=p,cutTriangles=mesh.triangles};}
 public static void Run(){EditorApplication.delayCall+=()=>{try{var doc=ScriptableObject.CreateInstance<StudioModelDocument>();doc.nodes.Add(Cube());host=ScriptableObject.CreateInstance<AnimationStudioWindow>();typeof(AnimationStudioWindow).GetField("modelingMode",F).SetValue(host,true);typeof(AnimationStudioWindow).GetField("modelDocument",F).SetValue(host,doc);typeof(AnimationStudioWindow).GetMethod("OpenViewport",F).Invoke(host,null);view=Resources.FindObjectsOfTypeAll<MashBoxStudioViewport>().Single(v=>v.Studio==host);view.position=new Rect(80,80,1000,750);editor=(StudioModelEditor)typeof(AnimationStudioWindow).GetField("modelEditor",F).GetValue(host);editor.SelectObject(0);Geometry();editor.ActivateCutTool(StudioModelEditor.CutTool.EdgeLoop);Call("SetEdgeLoopCount",1);Call("EstablishSelectionBaseline");view.LookAtDirect(Vector3.zero,Quaternion.Euler(12,25,0),2);SceneView.beforeSceneGui+=Before;SceneView.duringSceneGui+=After;EditorApplication.update+=Tick;next=EditorApplication.timeSinceStartup+2;}catch(Exception ex){Finish(ex);}};}
 static void Geometry()
 {
  stage="batched loop topology";
  foreach(int count in new[]{1,2,3,8,64})
  {
   var node=Cube();try{var source=node.mesh.vertices;for(int c=0;c<8;c++){var uv=source.Select(p=>new Vector4(p.x,p.y,p.z,.7f)).ToList();if(c%3==0)node.mesh.SetUVs(c,uv.Select(p=>new Vector2(p.x,p.y)).ToList());else if(c%3==1)node.mesh.SetUVs(c,uv.Select(p=>new Vector3(p.x,p.y,p.z)).ToList());else node.mesh.SetUVs(c,uv);}var topology=new StudioMeshCuts(node);var face=topology.Faces[0].Vertices;Set("cutTopology",topology);Call("SetEdgeLoopCount",count);var cuts=(List<StudioMeshCuts.Cut>)Call("BuildLoopCuts",new StudioMeshCuts.Point(face[0],face[1],.17f),true);Check(cuts.Count==4*count,"Wrong strip count for "+count);Check(source.SequenceEqual(node.mesh.vertices),"Preview wrote mesh");topology.Apply(node,cuts);var result=new StudioMeshCuts(node);Check(result.Faces.Count==6+4*count&&result.Faces.All(f=>f.Vertices.Count==4),"Batch cuts lost quad topology at "+count);Check(node.mesh.triangles.All(i=>i>=0&&i<node.mesh.vertexCount),"Bad triangle index");var fractions=node.mesh.vertices.Select(p=>Vector3.Dot(p-source[face[0]],source[face[1]]-source[face[0]])/(source[face[1]]-source[face[0]]).sqrMagnitude).ToArray();for(int i=1;i<=count;i++)Check(fractions.Any(t=>Math.Abs(t-i/(float)(count+1))<1e-5),"Missing evenly spaced center loop");for(int c=0;c<8;c++)Check(node.mesh.GetVertexAttributeDimension((UnityEngine.Rendering.VertexAttribute)((int)UnityEngine.Rendering.VertexAttribute.TexCoord0+c))==2+c%3,"UV dimension lost");}finally{Object.DestroyImmediate(node.mesh);}
  }
  Call("SetEdgeLoopCount",0);Check((int)Get("edgeLoopCount")==1,"Minimum count");Call("SetEdgeLoopCount",999);Check((int)Get("edgeLoopCount")==64,"Maximum count");Call("SetEdgeLoopCount",7);editor.ReloadStoredToolDefaults();Check((int)Get("edgeLoopCount")==7&&StudioPreferenceStore.GetFloat("Model.EdgeLoopCount",1)==7,"Count preference reload");
 }
 static void Before(SceneView scene){if(scene==view&&probe)Event.current.mousePosition=sent;}
 static void After(SceneView scene)
 {
  if(scene!=view)return;hot=GUIUtility.hotControl;if(renderPending&&Event.current.type==EventType.Layout){Handles.BeginGUI();GUILayout.BeginArea(new Rect(8,8,380,90));Call("DrawLoopCountOptions");GUILayout.EndArea();Handles.EndGUI();}if(Event.current.type!=EventType.Repaint)return;
  if(phase==0&&!probe)point=HandleUtility.WorldToGUIPoint(editor.Transforms[0].position);
  if(renderPending){renderPending=false;try{Render();}catch(Exception ex){renderFailure=ex;}}
 }
 static void Send(EventType type,Vector2 pointer,int button=0,EventModifiers modifiers=EventModifiers.None,Vector2 delta=default,KeyCode key=KeyCode.None){sent=pointer;probe=true;view.SendEvent(new Event{type=type,button=button,modifiers=modifiers,delta=delta,keyCode=key,mousePosition=pointer});probe=false;}
 static void Tick()
 {
  if(EditorApplication.timeSinceStartup<next)return;
  try
  {
   if(phase==0)
   {
    stage="native count wheel";view.SendEvent(new Event{type=EventType.Layout});view.SendEvent(new Event{type=EventType.Repaint});original=editor.ActiveMesh.vertices;polygons=(int[])editor.Document.nodes[0].cutPolygons.Clone();var transforms=editor.Transforms.ToArray();cameraPivot=view.pivot;cameraRotation=view.rotation;cameraSize=view.size;Reset();Send(EventType.MouseMove,point);Send(EventType.Layout,point);Check(((List<StudioMeshCuts.Cut>)Get("cutPreview")).Count==4,"No one-loop face-interior preview");Send(EventType.ScrollWheel,point,modifiers:EventModifiers.Control,delta:new Vector2(0,-3));Check((int)Get("edgeLoopCount")==2,"Ctrl wheel up did not add one loop");Check(view.size==cameraSize&&view.pivot==cameraPivot&&view.rotation==cameraRotation,"Count wheel moved camera");Check(((List<StudioMeshCuts.Cut>)Get("cutPreview")).Count==8,"Wheel did not rebuild preview immediately");Send(EventType.ScrollWheel,point,modifiers:EventModifiers.Control,delta:new Vector2(0,3));Check((int)Get("edgeLoopCount")==1,"Ctrl wheel down did not remove loop");Call("SetEdgeLoopCount",3);Check(original.SequenceEqual(editor.ActiveMesh.vertices)&&editor.Transforms.SequenceEqual(transforms)&&StudioUndo.RetainedActions==0,"Parameter preview changed mesh/scene/history");renderPending=true;Send(EventType.Layout,point);Send(EventType.Repaint,point);Check(!renderPending&&renderFailure==null,"Preview/slider render: "+renderFailure);phase=1;return;
   }
   if(phase==1)
   {
    stage="native centered middle click";Reset();Send(EventType.MouseDown,point,2);Send(EventType.MouseUp,point,2);Check(new StudioMeshCuts(editor.Document.nodes[0]).Faces.Count==18,"Middle click did not insert three loops");Check(StudioUndo.RetainedActions==1,"Middle click was not one Undo");Check(view.size==cameraSize&&view.pivot==cameraPivot&&view.rotation==cameraRotation,"Middle click moved camera");Check((StudioModelEditor.CutTool)Get("cutTool")==StudioModelEditor.CutTool.EdgeLoop,"Placement exited tool");History();Check(original.SequenceEqual(editor.ActiveMesh.vertices)&&polygons.SequenceEqual(editor.Document.nodes[0].cutPolygons),"Undo failed");History(true);Check(new StudioMeshCuts(editor.Document.nodes[0]).Faces.Count==18,"Redo failed");History();phase=2;return;
   }
   if(phase==2)
   {
    stage="native multi-loop drag cancel";Reset();Send(EventType.MouseMove,point);Send(EventType.Layout,point);Send(EventType.MouseDown,point);Check(hot!=0&&(bool)Get("cutDragging"),"Drag did not capture");Send(EventType.MouseDrag,point+new Vector2(15,8));Send(EventType.ScrollWheel,point+new Vector2(15,8),modifiers:EventModifiers.Control,delta:new Vector2(0,-3));Check((int)Get("edgeLoopCount")==4&&((List<StudioMeshCuts.Cut>)Get("cutPreview")).Count==16,"Count wheel during drag failed");Send(EventType.KeyDown,point,key:KeyCode.Escape);Check(!(bool)Get("cutDragging")&&original.SequenceEqual(editor.ActiveMesh.vertices)&&StudioUndo.RetainedActions==0,"Escape changed geometry/history");Send(EventType.MouseUp,point);Finish(null);
   }
  }catch(Exception ex){Finish(ex);}
 }
 static void Render()
 {
  var rt=new RenderTexture(500,400,24);rt.Create();var previous=RenderTexture.active;var target=view.camera.targetTexture;var rect=view.camera.pixelRect;bool xray=(bool)Get("displayXray");var position=view.camera.transform.position;var rotation=view.camera.transform.rotation;bool ortho=view.camera.orthographic;float orthoSize=view.camera.orthographicSize;var projection=view.camera.projectionMatrix;var worldToCamera=view.camera.worldToCameraMatrix;Set("displayXray",true);view.camera.transform.SetPositionAndRotation(new Vector3(2,1.3f,-3),Quaternion.LookRotation(new Vector3(-2,-1.3f,3)));view.camera.orthographic=true;view.camera.orthographicSize=1.3f;view.camera.ResetWorldToCameraMatrix();view.camera.ResetProjectionMatrix();GL.PushMatrix();try{view.camera.targetTexture=rt;view.camera.pixelRect=new Rect(0,0,500,400);Handles.SetCamera(new Rect(0,0,500,400),view.camera);RenderTexture.active=rt;GL.Clear(true,true,Color.black);GL.LoadProjectionMatrix(view.camera.projectionMatrix);GL.modelview=view.camera.worldToCameraMatrix;Call("DrawCutPreview",view);var image=new Texture2D(500,400,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,500,400),0,0);image.Apply();File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath,"../../loop-count-preview.png")),image.EncodeToPNG());var pixels=image.GetPixels32();int blue=pixels.Count(c=>c.a>100&&c.b>140&&c.b>c.g*1.15f);Check(blue>50,"Distinct blue preview lines missing: pixels="+blue+", cuts="+((List<StudioMeshCuts.Cut>)Get("cutPreview")).Count+", point="+point+", cameraSize="+view.size);var topology=(StudioMeshCuts)Get("cutTopology");var cuts=(List<StudioMeshCuts.Cut>)Get("cutPreview");Check(cuts.Count==12,"Rendered preview lost loop batch");var midpoints=cuts.Select(cut=>view.camera.WorldToScreenPoint(editor.Transforms[0].TransformPoint((topology.Position(cut.A)+topology.Position(cut.B))*.5f))).ToArray();Check(midpoints.Max(p=>p.x)-midpoints.Min(p=>p.x)>40&&midpoints.Max(p=>p.y)-midpoints.Min(p=>p.y)>40,"Render camera collapsed preview to a point");bool allLines=cuts.All(cut=>{var world=editor.Transforms[0].TransformPoint((topology.Position(cut.A)+topology.Position(cut.B))*.5f);var screen=view.camera.WorldToScreenPoint(world);for(int y=Mathf.Max(0,(int)screen.y-4);y<Mathf.Min(400,(int)screen.y+5);y++)for(int x=Mathf.Max(0,(int)screen.x-4);x<Mathf.Min(500,(int)screen.x+5);x++){var color=pixels[y*500+x];if(color.a>100&&color.b>140&&color.b>color.g*1.15f)return true;}return false;});Check(allLines,"A projected cut midpoint has no visible blue preview");Object.DestroyImmediate(image);Handles.BeginGUI();GUILayout.BeginArea(new Rect(8,8,380,90));Call("DrawLoopCountOptions");GUILayout.EndArea();Handles.EndGUI();}finally{Set("displayXray",xray);GL.PopMatrix();view.camera.transform.SetPositionAndRotation(position,rotation);view.camera.orthographic=ortho;view.camera.orthographicSize=orthoSize;view.camera.projectionMatrix=projection;view.camera.worldToCameraMatrix=worldToCamera;view.camera.targetTexture=target;view.camera.pixelRect=rect;RenderTexture.active=previous;Object.DestroyImmediate(rt);}
 }
 static void Finish(Exception ex){EditorApplication.update-=Tick;SceneView.beforeSceneGui-=Before;SceneView.duringSceneGui-=After;File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../loop-count-result.txt")),ex==null?"PASS "+checks+" batch topology/UV, count preferences, native wheel/middle/drag, rendering and Undo checks":stage+"\n"+ex);EditorApplication.delayCall+=()=>{if(view)view.Close();if(host)Object.DestroyImmediate(host);double exitAt=EditorApplication.timeSinceStartup+1;void Exit(){if(EditorApplication.timeSinceStartup<exitAt)return;EditorApplication.update-=Exit;EditorApplication.Exit(ex==null?0:1);}EditorApplication.update+=Exit;};}
}
